from pathlib import Path
R=Path(__file__).resolve().parent.parent
nav=[('index.html','Home'),('vision.html','The vision'),('lodges.html','Private lodges'),('living.html','Mountain living'),('land.html','The land')]
def link(url,label):return f'<a class="text-link" href="{url}">{label} <span aria-hidden="true">↗</span></a>'
def pic(name,alt,caption='Architectural concept · Mount Paradise',cls=''):
 return f'<figure class="{cls}"><a href="assets/{name}.jpg" data-lightbox aria-label="Enlarge: {alt}"><img src="assets/{name}.jpg" alt="{alt}" loading="lazy" width="1536" height="1024"></a><figcaption>{caption}<span>View artwork ↗</span></figcaption></figure>'
def intro(k,title,text):return f'<section class="section intro"><p class="eyebrow">{k}</p><div class="split"><h2>{title}</h2><div class="prose"><p>{text}</p></div></div></section>'
hero_alts={'signature-lodge':'Stone and timber Garden Lodge with a private pool and mountain backdrop','vista':'Vista Lodge with a long shaded veranda and pool terrace','terrace':'Tea and coffee on a timber veranda overlooking lush highland planting','landscape':'Spacious mountain landscape with distinct stone and timber homes set among trees'}
def hero(img,k,title,desc,home=False):return f'<section class="hero {"home" if home else "subhero"}"><img class="hero-image" src="assets/{img}.jpg" alt="{hero_alts.get(img, "Mount Paradise architectural concept")}" fetchpriority="high"><div class="hero-shade"></div><div class="hero-content"><p class="eyebrow">{k}</p><h1>{title}</h1><p class="hero-description">{desc}</p>{link("lodges.html" if home else "#discover","Explore private lodges" if home else "Discover more")}</div><div class="hero-bottom"><span>Trawas · East Java · Indonesia</span><span>Proposed design · Artist’s impression</span></div></section>'
def row(num,title,text):return f'<article class="principle"><span class="eyebrow">{num}</span><h3>{title}</h3><p>{text}</p></article>'
footer='''<footer><div class="footer-top"><p class="eyebrow">Mount Paradise · Trawas</p><h2>A little closer<br>to paradise.</h2><a class="text-link" href="vision.html">Discover the vision ↗</a></div><div class="footer-bottom"><span>© 2026 Mount Paradise</span><span>A mountain community in the making.</span><a href="#top">Back to top ↑</a></div><p class="disclosure">An early development vision. Renderings are proposed concepts, not completed residences or guaranteed views. Layouts, amenities and areas remain subject to site studies, design development and approvals.</p></footer>'''
exec((R / 'scripts' / 'pages.py').read_text())
exec((R / 'scripts' / 'tiers.py').read_text())
for file,(title,body) in pages.items():
 active='aria-current="page"'
 navhtml=''.join(f'<a href="{u}" {active if u==file or (u=="lodges.html" and file in ["lodge-tiers.html","garden-lodge.html"]) else ""}>{label}</a>' for u,label in nav)
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Mount Paradise, Trawas</title><meta name="description" content="Explore Mount Paradise: a vision for private stone and timber mountain lodges, lush gardens and thoughtful living in Trawas, East Java."><meta name="theme-color" content="#20362d"><meta property="og:title" content="{title} | Mount Paradise"><meta property="og:description" content="A private mountain sanctuary in Trawas. Explore the architecture, gardens and vision."><meta property="og:type" content="website"><meta property="og:image" content="https://civnexus.github.io/langit/assets/signature-lodge.jpg"><meta property="og:url" content="https://civnexus.github.io/langit/{file}"><meta name="twitter:card" content="summary_large_image"><link rel="canonical" href="https://civnexus.github.io/langit/{file}"><link rel="icon" href="assets/mark.svg" type="image/svg+xml"><link rel="stylesheet" href="styles.css"><script src="site.js" defer></script></head><body id="top" class="{"land-page" if file=="vision.html" else ""}"><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="index.html" aria-label="Mount Paradise home"><svg viewBox="0 0 80 34" aria-hidden="true"><path d="M3 31 29 4 43 21 53 10 77 31M17 25 29 16 37 21"/></svg><span>MOUNT PARADISE<small>T R A W A S</small></span></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menu <span>☰</span></button><nav id="navigation" aria-label="Main navigation">{navhtml}</nav></header><main id="main">{body}</main>{footer}<dialog class="lightbox"><button aria-label="Close artwork" class="close-lightbox">Close ×</button><img alt=""><p></p></dialog></body></html>'''
 (R/file).write_text(html)
(R/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>https://civnexus.github.io/langit/{f}</loc></url>' for f in pages)+'</urlset>')
print(f'Built {len(pages)} pages')
